CREATE TABLE IF NOT EXISTS version_state(modelId TEXT PRIMARY KEY REFERENCES model_manifests(id),revision INTEGER NOT NULL CHECK(revision>=0),evolutionJson TEXT NOT NULL,seedJson TEXT NOT NULL,lastRoundKey TEXT,updatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS version_state_events(id TEXT PRIMARY KEY,modelId TEXT NOT NULL REFERENCES model_manifests(id),revision INTEGER NOT NULL,evolutionJson TEXT NOT NULL,inputHash TEXT NOT NULL,at INTEGER NOT NULL,UNIQUE(modelId,revision));
CREATE TABLE IF NOT EXISTS version_observations(id TEXT PRIMARY KEY,jobId TEXT NOT NULL UNIQUE REFERENCES jobs(id),modelId TEXT NOT NULL REFERENCES model_manifests(id),predictionId TEXT REFERENCES predictions(id),fixtureRevisionId TEXT NOT NULL REFERENCES fixture_revisions(id),bundleId TEXT NOT NULL REFERENCES input_bundles(id),state TEXT NOT NULL CHECK(state IN('DONE','BLOCKED')),outputJson TEXT NOT NULL,outputHash TEXT NOT NULL,calculatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS version_ticket_evidence(ticketId TEXT PRIMARY KEY REFERENCES tickets(id),modelId TEXT NOT NULL REFERENCES model_manifests(id),originalJson TEXT NOT NULL,stateRevision INTEGER NOT NULL,at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS version_observation_fixture ON version_observations(fixtureRevisionId,modelId,calculatedAt);
CREATE TABLE IF NOT EXISTS version_execution_rejections(id TEXT PRIMARY KEY,modelId TEXT NOT NULL REFERENCES model_manifests(id),roundKey TEXT NOT NULL,policyId TEXT NOT NULL,businessKey TEXT NOT NULL,reason TEXT NOT NULL,originalJson TEXT NOT NULL,at INTEGER NOT NULL,UNIQUE(modelId,roundKey,policyId,businessKey));
